import React, { useEffect, useState } from "react";
import axios from "axios";
import PageHeader from "./PageHeader";
import SectionCard from "./SectionCard";
import DashboardCard from "./DashboardCard";
import AlertBox from "./AlertBox";
import { FaClipboardList, FaPlusCircle, FaUsers } from "react-icons/fa";
import "./dashboard.css";

function AssignmentsTeacher() {
  const teacherId = localStorage.getItem("user_id");

  const [courses, setCourses] = useState([]);
  const [assignments, setAssignments] = useState([]);
  const [submissions, setSubmissions] = useState([]);
  const [selectedSubjectCode, setSelectedSubjectCode] = useState("");
  const [selectedAssignment, setSelectedAssignment] = useState("");
  const [alert, setAlert] = useState(null);

  const [form, setForm] = useState({
    subject_code: "",
    title: "",
    description: "",
    due_date: ""
  });

  useEffect(() => {
    loadCourses();
  }, []);

  const loadCourses = async () => {
    try {
      const res = await axios.get("http://127.0.0.1:8000/courses");
      const all = res.data.courses || [];
      setCourses(all.filter(c => String(c.teacher_id) === String(teacherId)));
    } catch (err) {
      console.error(err);
    }
  };

  const loadAssignments = async (subjectCode) => {
    try {
      const res = await axios.get(`http://127.0.0.1:8000/assignments/${subjectCode}`);
      setAssignments(res.data.assignments || []);
    } catch (err) {
      console.error(err);
      setAssignments([]);
    }
  };

  const loadSubmissions = async (assignmentId) => {
    try {
      const res = await axios.get(`http://127.0.0.1:8000/assignment-submissions/${assignmentId}`);
      setSubmissions(res.data.submissions || []);
    } catch (err) {
      console.error(err);
      setSubmissions([]);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const payload = {
        ...form,
        teacher_id: parseInt(teacherId)
      };

      const res = await axios.post("http://127.0.0.1:8000/create-assignment", payload);

      setAlert({ message: res.data.message, type: "success" });
      setForm({
        subject_code: form.subject_code,
        title: "",
        description: "",
        due_date: ""
      });

      if (form.subject_code) {
        loadAssignments(form.subject_code);
      }
    } catch (err) {
      console.error(err);
      setAlert({ message: "Assignment creation failed", type: "error" });
    }
  };

  return (
    <div>
      {alert && <AlertBox {...alert} onClose={() => setAlert(null)} />}

      <PageHeader
        title="Assignments Panel"
        subtitle="Create subject-wise assignments and view student submissions."
      />

      <div className="grid-3" style={{ marginBottom: 20 }}>
        <DashboardCard icon={<FaClipboardList />} label="Assignments" value={assignments.length} />
        <DashboardCard icon={<FaUsers />} label="Submissions" value={submissions.length} />
        <DashboardCard icon={<FaPlusCircle />} label="Teacher Mode" value="Active" />
      </div>

      <div className="grid-2">
        <SectionCard title="Create Assignment">
          <form onSubmit={handleSubmit}>
            <select
              className="select"
              name="subject_code"
              value={form.subject_code}
              onChange={(e) => {
                setForm({ ...form, subject_code: e.target.value });
                setSelectedSubjectCode(e.target.value);
                loadAssignments(e.target.value);
              }}
            >
              <option value="">Select Subject</option>
              {courses.map(c => (
                <option key={c.id} value={c.subject_code}>
                  {c.title} ({c.subject_code})
                </option>
              ))}
            </select>

            <input
              className="input"
              name="title"
              placeholder="Assignment Title"
              value={form.title}
              onChange={(e) => setForm({ ...form, title: e.target.value })}
            />

            <textarea
              className="textarea"
              name="description"
              placeholder="Question / Description"
              value={form.description}
              onChange={(e) => setForm({ ...form, description: e.target.value })}
            />

            <input
              className="input"
              type="date"
              name="due_date"
              value={form.due_date}
              onChange={(e) => setForm({ ...form, due_date: e.target.value })}
            />

            <button className="btn btn-primary" type="submit">
              Create Assignment
            </button>
          </form>
        </SectionCard>

        <SectionCard title="Assignments List">
          <select
            className="select"
            value={selectedAssignment}
            onChange={(e) => {
              setSelectedAssignment(e.target.value);
              loadSubmissions(e.target.value);
            }}
          >
            <option value="">Select Assignment</option>
            {assignments.map(a => (
              <option key={a.id} value={a.id}>{a.title}</option>
            ))}
          </select>

          {assignments.map(a => (
            <div className="list-card" key={a.id}>
              <h4>{a.title}</h4>
              <div className="meta">{a.description}</div>
              <div className="meta">Subject Code: {a.subject_code}</div>
              <div className="meta">Due: {a.due_date}</div>
            </div>
          ))}
        </SectionCard>
      </div>

      <SectionCard title="Student Submissions">
        {submissions.length === 0 ? (
          <p>No submissions</p>
        ) : (
          submissions.map(s => (
            <div className="list-card" key={s.id}>
              <p><strong>{s.student_name}</strong></p>
              <a href={`http://127.0.0.1:8000${s.file_url}`} target="_blank" rel="noreferrer">
                View File
              </a>
            </div>
          ))
        )}
      </SectionCard>
    </div>
  );
}

export default AssignmentsTeacher;
